theme.sections/test-section.liquid:
{% schema %}
{
  "name": "Section name",
  "settings": [
    {
      "id": "text_value",
      "type": "text",
      "label": "Text Value",
      "default": "Some text without liquid logic."
    }
  ]
}
{% endschema %}

{% schema %}
{
  "name": "Section name",
  "settings": [
    {
      "id": "input_with_logic",
      "type": "text",
      "label": "Input with Logic",
      "default": "Hello {% if user %} User {% endif %}!"
    }
  ]
}
{% endschema %}

  {% schema %}
  {
    "name": "test",
    "settings": {
      "text_block": {
        "type": "text",
        "id": "text_block",
        "label": "Text Block",
        "default": "Hello {% if user %} User {% endif %}!"
      }
    }
  }
{% endschema %}

{% schema %}
{
  "name": "Section name",
  "presets": [
    {
      "name": "Default",
      "block": [
        {
          "type": "text",
          "settings": {
            "text": "Hello World!{% random liquid logic %}"
          }
        }
      ]
    }
  ]
}
{% endschema %}

  {% schema %}
  {
    "name": "test",
    "settings": {
      "text_block": {
        "type": "text",
        "id": "text_block",
        "label": "Text Block",
        "default": "Hello World!",
        "visible_if": "{% if user %} true {% endif %}"
      }
    }
  }
{% endschema %}

